const REPORT_YEARS=[2023,2024,2025];
function normalizeCompany(c){c=standardizeBusiness(c);if(c.investmentUnit!=='million'){c={...c,raised:String(Number(c.raised||0)*100),investmentUnit:'million'}}if(c.employmentBasis!=='new'){c={...c,employmentBasis:'new',annuals:Object.fromEntries(Object.entries(c.annuals||{}).map(([year,row])=>[year,{...row,legacyEmployment:row.employment,employment:null}]))}}const {raising,target,...rest}=c;return {...rest,entityType:c.entityType||'',legalForm:c.legalForm||'',businessNo:c.businessNo||'',corporateNo:c.corporateNo||'',workplaces:companyWorkplaces(c),headOffice:c.headOffice||c.city||'',factory:c.factory||'',lab:c.lab||'',representatives:c.representatives?.length?c.representatives:[{name:c.ceo||'',birthDate:''}],annuals:c.annuals||{},reviewStatus:c.reviewStatus||(c.visible?'approved':'hidden')};}
function isCompanyOwner(c){return user?.role==='company'&&(c.owner===user.email||(user.email==='company@demo.local'&&c.id==='1'&&!c.owner));}
function profileField(label,name,value='',options={}){return `<label class="field">${label}${options.optional?'<span class="optional">선택</span>':'<span class="required-mark">필수</span>'}<input name="${name}" type="${options.type||'text'}" value="${esc(value)}" ${options.optional?'':'required'} ${options.type==='number'?'min="0" step="'+(options.integer?'1':'0.01')+'"':''} ${options.pattern?'pattern="'+options.pattern+'"':''} ${options.max?'max="'+options.max+'"':''} maxlength="${INPUT_LIMITS[name]||options.length||200}" ${options.placeholder?'placeholder="'+options.placeholder+'"':''}></label>`;}
function optionPicker(name,label,options,value,required=true){return `<div class="field picker-field">${label}<span class="required-mark">필수</span><input type="text" class="picker-value" tabindex="-1" aria-label="${label}" name="${name}" value="${esc(value)}" ${required?'required':''}><details class="profile-picker" data-picker="${name}"><summary><span>${esc(options.find(x=>x[0]===value)?.[1]||(name==='businessSector'?'사업 분야를 선택해 주세요':'선택해 주세요'))}</span><span class="chevron"></span></summary><div class="profile-options">${options.map(([v,l])=>`<button type="button" class="${value===v?'selected':''}" data-value="${esc(v)}">${esc(l)}${value===v?' <span aria-hidden="true">✓</span>':''}</button>`).join('')}</div></details></div>`;}
function section(number,title,description){return `<div class="section-title"><span>${number}</span><div><h2>${title}</h2><p>${description}</p></div></div>`;}
function representativeRow(rep,index){return `<div class="representative-row"><div class="formgrid">${profileField(index===0?'대표자 성명':'공동대표 성명','repName',rep.name)}${profileField('출생연도','repBirth',String(rep.birthYear||rep.birthDate||'').slice(0,4),{length:4,pattern:'[0-9]{4}',placeholder:'예: 1985'})}</div>${index>0?'<button type="button" class="btn remove-representative">공동대표 삭제</button>':''}</div>`;}
function reviewLabel(c){return c.visible?'공개 중':c.reviewStatus==='pending'?'검토 대기':'비노출';}
function companyPage(raw){const c=normalizeCompany(raw);shell(`<div class="topline company-topline"><div><div class="eyebrow">MY COMPANY</div><h1>내 기업정보 관리</h1><p class="muted">저장한 기업정보는 비노출 상태로 접수되며 관리자 확인 후 공개됩니다.</p></div>${c.id?`<a class="btn" href="#/company/${c.id}">기업정보 미리보기 ↗</a>`:''}</div><div class="review-banner"><span class="review-pill">${c.id?reviewLabel(c):'등록 전'}</span><span>${c.visible?'정보를 수정·저장하면 비노출 상태로 전환되어 다시 검토합니다.':'관리자가 확인 후 공개하면 기업 목록에 표시됩니다.'}</span></div><form id="companyform" class="panel" novalidate><div id="form-errors" class="form-errors" role="alert" hidden></div>${section('01','기업 소개','주된 시장에 맞는 사업 분야와 핵심 아이템을 알려주세요.')}<div class="formgrid profile-basic">${profileField('기업명','name',c.name,{length:30,placeholder:'정식 기업명, 최대 30자'})}${optionPicker('businessSector','사업 분야',BUSINESS_SECTORS.map(s=>[s,s]),c.businessSector)}<div class="full">${profileField('사업 아이템 한 줄 소개','oneLineDescription',c.oneLineDescription,{length:50,placeholder:'기업의 핵심 제품이나 서비스를 한 문장으로 설명해 주세요'})}<p class="smallnote description-help">투자사가 기업의 핵심 아이템을 빠르게 이해할 수 있도록 한 문장으로 작성해 주세요. 공백 포함 최대 50자.</p></div></div>${section('02','대표자 정보','출생연도은 기업 본인과 관리자 화면에만 표시됩니다.')}<div id="representatives">${c.representatives.map(representativeRow).join('')}</div><button type="button" class="btn" id="add-representative">＋ 공동대표 추가</button>${section('03','사업장 소재지','본점은 1곳, 전체 사업장은 최대 5곳까지 등록할 수 있습니다.')}<div id="workplaces">${c.workplaces.map(workplaceRow).join('')}</div><button type="button" class="btn" id="add-workplace">＋ 사업장 추가</button>${section('04','기업 등록정보','설립일과 사업자 정보를 입력해 주세요.')}<div class="formgrid profile-basic">${profileField('설립일','founded',c.founded,{type:'date',max:new Date().toISOString().slice(0,10)})}${optionPicker('entityType','사업자 유형',[['corporate','법인사업자'],['individual','개인사업자']],c.entityType)}<div id="legal-form-wrap">${optionPicker('legalForm','법인 형태',[['주식회사','주식회사'],['유한회사','유한회사'],['유한책임회사','유한책임회사'],['합명회사','합명회사'],['합자회사','합자회사'],['기타 법인','기타 법인']],c.legalForm)}</div>${profileField('사업자등록번호','businessNo',c.businessNo,{pattern:'[0-9]{3}-?[0-9]{2}-?[0-9]{5}',length:12,placeholder:'000-00-00000'})}<div id="corporate-no-wrap">${profileField('법인등록번호','corporateNo',c.corporateNo,{pattern:'[0-9]{6}-?[0-9]{7}',length:14,placeholder:'000000-0000000'})}</div></div><div class="formgrid profile-basic">${optionPicker('stage','투자 단계',INVESTMENT_STAGES.map(s=>[s,s]),INVESTMENT_STAGES.includes(c.stage)?c.stage:'')}${profileField('누적 투자유치액 (백만원)','raised',c.raised||'0',{type:'number'})}</div>${section('05','최근 3개년 실적 (선택)','실적이 없으면 0, 아직 확인되지 않은 항목은 빈칸으로 남겨주세요. 투자는 해당 연도에 유치한 금액입니다.')}<div class="tablewrap annual-inputs"><table><thead><tr><th>연도</th><th>매출 (백만원)</th><th>신규 고용 (명)</th><th>투자유치액 (백만원)</th></tr></thead><tbody>${REPORT_YEARS.map(y=>`<tr><th>${y}년</th>${['revenue','employment','investment'].map((key,i)=>`<td><input aria-label="${y}년 ${['매출 백만원','신규 고용 명','투자유치액 백만원'][i]}" name="${key}_${y}" type="number" min="0" step="${key==='employment'?'1':'0.01'}" value="${esc(c.annuals[y]?.[key]??'')}" placeholder="-"></td>`).join('')}</tr>`).join('')}</tbody></table></div>${section('06','IR 자료','기업을 소개할 자료를 업로드하세요.')}<label class="field">IR 자료 (PDF만 지원, 최대 30MB)<span class="required-mark">필수</span><input id="irfile" ${hasPdf(c)?'':'required'} type="file" accept=".pdf,application/pdf"></label><p class="smallnote">${hasPdf(c)?'현재 자료: '+esc(pdfName(c)):'PDF를 등록해 주세요. 기존 PDF 외 자료는 재업로드가 필요합니다.'} 저장·다운로드 파일명: 기업명_IR.pdf</p><div class="form-save"><span class="smallnote">저장 후 관리자 검토가 완료되면 공개됩니다.</span><button class="btn primary" id="save-company">저장하고 검토 요청</button></div></form>`);
const form=$('#companyform');bindEnhancedInputs(form);bindGroupedNumbers(form);bindWorkplaces(form);bindFoundedCalendar(form);
function syncEntity(){const individual=form.elements.entityType.value==='individual';for(const id of ['legal-form-wrap','corporate-no-wrap']){const wrap=$('#'+id);wrap.hidden=individual||!form.elements.entityType.value;wrap.querySelectorAll('input').forEach(input=>{input.disabled=individual||!form.elements.entityType.value;input.required=!input.disabled;input.setCustomValidity('');});}}
form.querySelectorAll('.profile-picker').forEach(picker=>{picker.querySelectorAll('button').forEach(button=>button.onclick=()=>{const input=picker.parentElement.querySelector('input');input.value=button.dataset.value;input.setCustomValidity('');picker.querySelector('summary span').textContent=button.textContent.replace('✓','').trim();picker.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===button);b.querySelector('span')?.remove()});picker.open=false;picker.querySelector('summary').focus();if(input.name==='entityType')syncEntity();});picker.parentElement.querySelector('input').addEventListener('invalid',e=>{e.preventDefault();picker.open=true;picker.querySelector('summary').focus();toast('필수 선택 항목을 확인해 주세요.');});});syncEntity();
const repButton=$('#add-representative');repButton.hidden=c.representatives.length>=2;repButton.textContent='＋ 공동대표 추가 (최대 1명)';repButton.onclick=()=>{if($('#representatives').children.length>=2)return;$('#representatives').insertAdjacentHTML('beforeend',representativeRow({name:'',birthDate:''},1));repButton.hidden=true;};$('#representatives').onclick=e=>{if(e.target.classList.contains('remove-representative')){e.target.closest('.representative-row').remove();repButton.hidden=$('#representatives').children.length>=2;}};
form.onsubmit=async e=>{e.preventDefault();if(!validateCompanyForm(form))return;const file=$('#irfile').files[0];if(file){try{await validatePdf(file)}catch(err){return toast(err.message)}}if(!file){try{if(!hasPdf(c))throw Error('IR PDF 자료를 등록해 주세요.');await readPdf(c);}catch(err){toast(err.message);$('#irfile').focus();return;}}const fd=new FormData(form);form.querySelectorAll('[data-numeric]').forEach(input=>fd.set(input.name,numericValue(input.value)));let obj;try{obj=collectCompany(c,fd);}catch(err){return toast(err.message);}const button=$('#save-company');button.disabled=true;try{if(file){obj.irKey=await storePdf(file);delete obj.irData;obj.irName=pdfName(obj);}else obj.irName=hasPdf(obj)?pdfName(obj):'';const next=c.id?companies.map(x=>x.id===c.id?obj:x):[obj,...companies];localStorage.setItem('jb-companies',JSON.stringify(next));companies=next;toast('저장되었습니다. 관리자 검토 후 공개됩니다.');mypage();}catch(err){button.disabled=false;toast(err.name==='QuotaExceededError'?'브라우저 저장 공간이 부족합니다. 파일 크기를 줄여주세요.':err.message);}};
}
function collectCompany(c,fd,logoData){const data=validateEnhancedData(Object.fromEntries(fd),fd);const workplaces=collectWorkplaces(fd);const main=workplaces.find(w=>w.type==='본점');data.headOffice=main.address;data.headOfficeDetail=main.detail;data.workplaces=workplaces;for(const [type,key] of [['공장','factory'],['연구소','lab']]){data[key]=workplaces.filter(w=>w.type===type).map(w=>w.address).join(' / ');data[key+'Detail']='';}for(const key of Object.keys(data))if(key.startsWith('workplace_'))delete data[key];for(const [key,label] of [['founded','설립일'],['raised','누적 투자유치액']])if(!String(data[key]??'').trim())throw Error(label+'을 입력해 주세요.');const foundedDate=new Date(data.founded+'T12:00:00');if(isNaN(foundedDate)||foundedDate>new Date()||[foundedDate.getFullYear(),String(foundedDate.getMonth()+1).padStart(2,'0'),String(foundedDate.getDate()).padStart(2,'0')].join('-')!==data.founded)throw Error('올바른 설립일을 입력해 주세요.');if(!INVESTMENT_STAGES.includes(data.stage))throw Error('투자 단계를 목록에서 선택해 주세요.');data.investmentUnit='million';data.employmentBasis='new';if(!Number.isFinite(Number(data.raised))||Number(data.raised)<0)throw Error('누적 투자유치액을 0 이상의 숫자로 입력해 주세요.');const representatives=fd.getAll('repName').map((name,i)=>({name:String(name).trim(),birthYear:String(fd.getAll('repBirth')[i]||'').trim()}));if(!representatives.length||representatives.length>2||representatives.some(r=>!r.name||r.name.length>5||!/^\d{4}$/.test(r.birthYear)||Number(r.birthYear)<1900||Number(r.birthYear)>new Date().getFullYear()))throw Error('대표자 이름과 출생연도을 확인해 주세요.');if(!['corporate','individual'].includes(data.entityType))throw Error('사업자 유형을 선택해 주세요.');if(!BUSINESS_SECTORS.includes(data.businessSector))throw Error('사업 분야를 목록에서 1개 선택해 주세요.');data.oneLineDescription=String(data.oneLineDescription||'').trim();if(!data.oneLineDescription||data.oneLineDescription.length>MAX_ONE_LINE_LENGTH||/[\r\n]/.test(data.oneLineDescription))throw Error('한 줄 소개는 1~50자의 한 문장으로 입력해 주세요.');data.sector=data.businessSector;data.summary=data.oneLineDescription;if(!/^\d{3}-?\d{2}-?\d{5}$/.test(data.businessNo))throw Error('사업자등록번호는 숫자 10자리로 입력해 주세요.');if(data.entityType==='corporate'&&(!data.legalForm||!/^\d{6}-?\d{7}$/.test(data.corporateNo)))throw Error('법인 형태와 13자리 법인등록번호를 확인해 주세요.');const annuals={};for(const y of REPORT_YEARS){annuals[y]={};for(const k of ['revenue','employment','investment']){const v=fd.get(k+'_'+y);if(v!==''&&v!==null&&(!Number.isFinite(Number(v))||Number(v)<0||(k==='employment'&&!Number.isInteger(Number(v)))))throw Error('실적은 0 이상, 고용인원은 정수로 입력해 주세요.');annuals[y][k]=v===''||v===null?null:Number(v);delete data[k+'_'+y];}}delete data.repName;delete data.repBirth;const out={...c,...data,id:c.id||Date.now().toString(),logoData,owner:user.email,representatives,ceo:representatives.map(r=>r.name).join(', '),annuals,city:data.headOffice,visible:false,reviewStatus:'pending',createdAt:c.createdAt||(c.id?new Date(companyRegisteredTime(c)).toISOString():new Date().toISOString()),submittedAt:new Date().toISOString()};if(data.entityType==='individual'){out.legalForm='';out.corporateNo='';}delete out.logo;delete out.logoData;delete out.raising;delete out.target;return standardizeBusiness(out);}
function factItems(items){return items.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'미입력')}</dd></div>`).join('');}
function annualTable(c){return `<div class="tablewrap"><table><thead><tr><th>연도</th><th>매출 (백만원)</th><th>신규 고용 (명)</th><th>투자 (백만원)</th></tr></thead><tbody>${REPORT_YEARS.map(y=>`<tr><th>${y}</th>${['revenue','employment','investment'].map(k=>`<td>${c.annuals?.[y]?.[k]==null?'-':esc(groupedNumber(c.annuals[y][k]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function companyDetail(id){const raw=companies.find(c=>c.id===id&&(c.visible||user?.role==='admin'||isCompanyOwner(c)));if(!raw){shell('<div class="empty">현재 공개되지 않은 기업입니다.<br><br><a class="btn" href="#/">기업 목록으로</a></div>');return;}const c=normalizeCompany(raw),privateView=user?.role==='admin'||isCompanyOwner(c);shell(`<a class="back" href="${user?.role==='admin'?'#/admin':isCompanyOwner(c)?'#/mypage':'#/'}">← ${user?.role==='admin'?'관리자페이지':isCompanyOwner(c)?'마이페이지':'기업 목록'}</a>${!c.visible?`<div class="visibility-note">${reviewLabel(c)} · 기업 본인과 관리자에게만 표시됩니다.</div>`:''}<div class="detail-title"><div><h1>${esc(c.name)}</h1><p>${esc(c.oneLineDescription)}</p><dl class="identity-facts"><div><dt>사업 분야</dt><dd>${esc(c.businessSector)}</dd></div></dl></div></div><div class="detail-layout"><div><section class="panel"><h2>기업 기본정보</h2><dl class="facts">${factItems([['대표자',c.ceo],['설립일',c.founded],['사업자 유형',c.entityType==='individual'?'개인사업자':c.entityType==='corporate'?'법인사업자':''],['법인 형태',c.entityType==='individual'?'해당 없음':c.legalForm],['사업자등록번호',c.businessNo],['법인등록번호',c.entityType==='individual'?'해당 없음':c.corporateNo],['사업 분야',c.businessSector]])}</dl></section><section class="panel"><h2>사업장 소재지</h2><dl class="facts location-facts">${factItems(companyWorkplaces(c).map((w,i)=>[w.type+' '+(i+1),[w.address,w.detail].filter(Boolean).join(' ')]))}</dl></section>${privateView?`<section class="panel"><h2>대표자 정보</h2><p class="smallnote">기업 본인·관리자 전용</p><dl class="facts">${factItems(c.representatives.map((r,i)=>[i===0?'대표자':'공동대표',r.name+' · '+(r.birthYear||String(r.birthDate||'').slice(0,4)||'출생연도 미입력')]))}</dl></section>`:''}<section class="panel"><h2>최근 3개년 실적</h2><p class="smallnote">고용은 해당 연도 신규 채용 인원, 투자는 해당 연도 유치금액입니다.</p>${annualTable(c)}</section></div><aside>${user?.role==='admin'?`<div class="panel"><h3>공개 관리</h3><p>${reviewLabel(c)}</p><button class="btn primary wide" onclick="toggleVisibility('${c.id}')">${c.visible?'비노출로 전환':'확인 완료 · 공개하기'}</button></div>`:''}<div class="panel"><h3>투자정보</h3><dl class="facts">${factItems([['누적 투자유치',c.raised+'백만원'],['최근 투자단계',c.stage]])}</dl></div><div class="panel"><h3>IR 자료</h3><p style="overflow-wrap:anywhere">${hasPdf(c)?esc(pdfName(c)):'등록된 PDF 없음'}</p><button class="btn primary wide" ${hasPdf(c)?'':'disabled'} onclick="ir('${c.id}')">↓ IR PDF 다운로드</button></div>${c.visible?`<button class="btn wide" onclick="favorite('${c.id}')">${(favorites[user?.email]||[]).includes(c.id)?'♥ 관심기업 저장됨':'♡ 관심기업 저장'}</button>`:''}</aside></div>`);}
function exportCompanyRows(){const columns=[['기업명',c=>c.name],['사업자 유형',c=>c.entityType==='individual'?'개인사업자':c.entityType==='corporate'?'법인사업자':''],['법인 형태',c=>c.legalForm],['사업자등록번호',c=>c.businessNo],['법인등록번호',c=>c.corporateNo],['대표자 전체',c=>c.representatives.map(r=>r.name).join(' / ')],['대표자 출생연도',c=>c.representatives.map(r=>r.name+': '+(r.birthYear||String(r.birthDate||'').slice(0,4))).join(' / ')],['사업 분야',c=>c.businessSector],['전체 사업장',c=>companyWorkplaces(c).map(w=>w.type+': '+w.address+' '+w.detail).join('\n')],['본점',c=>c.headOffice],['공장',c=>c.factory],['연구소',c=>c.lab],['설립일',c=>c.founded],['한 줄 소개',c=>c.summary],['누적 투자(백만원)',c=>c.raised],['투자단계',c=>c.stage],['공개 상태',reviewLabel],['검토 요청일',c=>c.submittedAt],['IR 파일명',c=>hasPdf(c)?pdfName(c):''],['본점 상세주소',c=>c.headOfficeDetail],['공장 상세주소',c=>c.factoryDetail],['연구소 상세주소',c=>c.labDetail]];for(const y of REPORT_YEARS)for(const [k,l] of [['revenue','매출(백만원)'],['employment','신규 고용(명)'],['investment','투자(백만원)']])columns.push([y+' '+l,c=>c.annuals?.[y]?.[k]]);return [columns.map(x=>x[0]),...companies.map(normalizeCompany).map(c=>columns.map(([,fn])=>fn(c)??''))];}
function excelColumn(index){let result='';for(let n=index+1;n>0;n=Math.floor((n-1)/26))result=String.fromCharCode(65+(n-1)%26)+result;return result;}
